### Code Examples

#### Example 1: Handling Errors in map()

```python
import multiprocessing
import traceback

def risky_function(x):
    """Function that might raise exceptions"""
    if x == 5:
        raise ValueError(f"Cannot process {x}!")
    if x == 8:
        raise ZeroDivisionError("Divide by zero!")
    return x ** 2

if __name__ == "__main__":
    items = list(range(10))

    with multiprocessing.Pool(4) as pool:
        try:
            results = pool.map(risky_function, items)
            print(f"Results: {results}")
        except Exception as e:
            print(f"Error occurred: {type(e).__name__}: {e}")
            # Note: You only get the first error
```

#### Example 2: Handling Errors Individually with apply_async()

```python
import multiprocessing
import traceback

def process_item(x):
    """Function that might fail"""
    if x % 3 == 0:
        raise ValueError(f"Don't like multiples of 3: {x}")
    return x ** 2

if __name__ == "__main__":
    items = list(range(10))

    with multiprocessing.Pool(4) as pool:
        # Submit all tasks
        async_results = [(x, pool.apply_async(process_item, (x,))) for x in items]

        # Collect results, handling errors individually
        results = {}
        errors = {}

        for x, ar in async_results:
            try:
                results[x] = ar.get()
            except Exception as e:
                errors[x] = str(e)

    print("Successful results:")
    for x, result in sorted(results.items()):
        print(f"  {x}: {result}")

    print("\nErrors:")
    for x, error in sorted(errors.items()):
        print(f"  {x}: {error}")
```

#### Example 3: Wrapping Functions to Catch Errors

```python
import multiprocessing
import traceback

def safe_wrapper(func):
    """Wrapper that catches exceptions and returns them"""
    def wrapped(*args, **kwargs):
        try:
            return {'success': True, 'result': func(*args, **kwargs)}
        except Exception as e:
            return {
                'success': False,
                'error': str(e),
                'traceback': traceback.format_exc()
            }
    return wrapped

def risky_computation(x):
    """Function that might fail"""
    if x < 0:
        raise ValueError("Negative values not allowed")
    return x ** 0.5  # Square root

if __name__ == "__main__":
    # Wrap the function
    safe_compute = safe_wrapper(risky_computation)

    items = [-5, 4, -3, 16, 25, -1, 9]

    with multiprocessing.Pool(4) as pool:
        results = pool.map(safe_compute, items)

    for x, result in zip(items, results):
        if result['success']:
            print(f"√{x} = {result['result']:.2f}")
        else:
            print(f"√{x} = ERROR: {result['error']}")
```
